lemma unprovable_either (T_consis : T.Consistent H) : ¬(T *⊢[H]! φ ∧ T *⊢[H]! ∼φ) := by
  by_contra hC;
  have ⟨hC₁, hC₂⟩ := hC;
  have : T *⊢[H]! ⊥ := neg_mdp! hC₂ hC₁;
  have : T *⊬[H] ⊥ := unprovable_falsum T_consis;
  contradiction;

